+    public boolean equals(Object o) {
+        if (this == o) {
+            return true;
+        }
+        if (o == null || getClass() != o.getClass()) {
+            return false;
+        }
+        WatermarkEvent that = (WatermarkEvent) o;
+        return isAligned == that.isAligned && Objects.equals(watermark, that.watermark);
+    }
